import{_ as a,o as e,c as d,a2 as o}from"./chunks/framework.CHeM0PsO.js";const x=JSON.parse('{"title":"Codex 从零到一","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),r={name:"index.md"};function l(i,t,n,s,h,c){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="codex-从零到一" tabindex="-1">Codex 从零到一 <a class="header-anchor" href="#codex-从零到一" aria-label="Permalink to &quot;Codex 从零到一&quot;">​</a></h1><h2 id="让-ai-帮你搞定编程与办公" tabindex="-1">让 AI 帮你搞定编程与办公 <a class="header-anchor" href="#让-ai-帮你搞定编程与办公" aria-label="Permalink to &quot;让 AI 帮你搞定编程与办公&quot;">​</a></h2><blockquote><p>面向零编程基础的职场人士和内容创作者<br> 用自然语言，让 AI 成为你的私人助手</p></blockquote><h2 id="课程简介" tabindex="-1">课程简介 <a class="header-anchor" href="#课程简介" aria-label="Permalink to &quot;课程简介&quot;">​</a></h2><p>你有没有过这样的经历？</p><ul><li>想写个小工具整理文件，但不会编程</li><li>要做一份 PPT，从找资料到排版折腾半天</li><li>想分析一堆数据，Excel 公式翻遍搜索引擎还是搞不定</li><li>听说 AI 能帮人写代码、做办公，但自己完全不知道从哪里开始</li></ul><p>如果你中了一条以上，这门课就是为你准备的。</p><p><strong>Codex 是 OpenAI 推出的 AI 编程智能体（coding agent）</strong>。它不是简单的&quot;聊天机器人&quot;，也不是只会补全代码的工具——它能读你的项目、写代码、运行命令、调用工具，甚至能帮你整理电脑文件夹、生成 PPT、做数据分析。</p><p>更重要的是：<strong>你不需要会编程</strong>。只要你会说人话，就能用 Codex 完成这些任务。</p><h2 id="课程结构" tabindex="-1">课程结构 <a class="header-anchor" href="#课程结构" aria-label="Permalink to &quot;课程结构&quot;">​</a></h2><p>本课程共 <strong>6 个模块</strong>，约 <strong>16 节课 + 4 个实战项目</strong>：</p><table tabindex="0"><thead><tr><th>模块</th><th>内容</th><th>时长</th></tr></thead><tbody><tr><td>模块一</td><td>认识 Codex</td><td>45 分钟</td></tr><tr><td>模块二</td><td>上手准备</td><td>60 分钟</td></tr><tr><td>模块三</td><td>核心功能</td><td>90 分钟</td></tr><tr><td>模块四</td><td>实用技巧</td><td>45 分钟</td></tr><tr><td>模块五</td><td>项目实战</td><td>120 分钟</td></tr><tr><td>模块六</td><td>总结与进阶</td><td>30 分钟</td></tr></tbody></table><p><strong>总计约 5-7 小时</strong>，可分模块学习。</p><h2 id="开始学习" tabindex="-1">开始学习 <a class="header-anchor" href="#开始学习" aria-label="Permalink to &quot;开始学习&quot;">​</a></h2><p><a href="/modules/module-1/lesson-1.md" class="btn-primary">→ 开始第 1 课</a></p><h2 id="学完你能做到什么" tabindex="-1">学完你能做到什么？ <a class="header-anchor" href="#学完你能做到什么" aria-label="Permalink to &quot;学完你能做到什么？&quot;">​</a></h2><ul><li>✅ 让 Codex 帮你整理文件夹、批量重命名、归类文件</li><li>✅ 用自然语言描述需求，让 Codex 生成网页或小工具</li><li>✅ 让 Codex 联网搜索资料并整理成报告</li><li>✅ 让 Codex 执行重复性任务，节省时间</li><li>✅ 使用 Codex 内置技能快速完成复杂任务（如生成 PPT）</li></ul>',17)])])}const u=a(r,[["render",l]]);export{x as __pageData,u as default};
